P.entries["item:acceptable-hyena-sample"] = {n="Acceptable Hyena Sample",s="Un campione accettabile di iena è un dato raccolto a Tanaris con il kit di test sul campo del Capo Ingegnere Segachiodi. Fa parte del suo censimento della fauna del deserto.",h="Un campione accettabile di iena è un dato raccolto a Tanaris con il kit di test sul campo del Capo Ingegnere...",kw={"campione accettabile di iena","capo ingegnere segachiodi","raccolta sul campo","kit di test sul campo","meccania","iena","tanaris"},sec={{t="Campioni del deserto",b="A Tanaris, il kit di test sul campo può ricavare un campione accettabile di iena da uno non ancora testato. Il Capo Ingegnere Segachiodi ha bisogno di otto campioni di iena, oltre a quelli di basilischi e scorpioni, per il suo censimento. La fonte di energia del kit ti dà due ore per raccogliere i dati prima che vadano persi."}},faq={{q="Cos'è un campione accettabile di iena?",a="Un campione accettabile di iena è un dato raccolto da un campione di iena non ancora testato con il kit di test sul campo di Segachiodi.",al={"campione di iena","campione accettabile di iena"}},{q="Chi ha bisogno di campioni di iena?",a="Il Capo Ingegnere Segachiodi a Meccania ha bisogno di otto campioni accettabili di iena per il suo censimento sul campo a Tanaris.",al={"chi vuole campioni di iena","campione di segachiodi"}},{q="Di quanti campioni di iena ha bisogno Segachiodi?",a="Segachiodi ha bisogno di otto campioni accettabili di iena e di otto campioni ciascuno di basilischi e scorpioni.",al={"numero di campioni di iena","quanti campioni"}},{q="Perché c'è un limite di tempo?",a="La fonte di energia del kit di test sul campo ti dà due ore per raccogliere i dati. Se si esaurisce, i dati al suo interno vanno persi.",al={"limite di energia del kit","dati persi"}}},fp="23,167,14.294.0,35.114.0,24.107.0,46.102.0,26.120.0"}
P.entries["item:acceptable-scorpid-sample"] = {n="Acceptable Scorpid Sample",s="Un campione accettabile di scorpide è un dato raccolto con un Field Testing Kit a Tanaris. Capo Ingegnere Segachiodi lo vuole insieme agli altri campioni per il suo studio sul campo.",h="Un campione accettabile di scorpide è un dato raccolto con un Field Testing Kit a Tanaris.",kw={"campione accettabile di scorpide","segachiodi","field testing kit","meccania","campione","scorpide","scorpione","tanaris"},sec={{t="Dati dal deserto",b="Il Field Testing Kit raccoglie dati sugli scorpidi a Tanaris per Capo Ingegnere Segachiodi di Meccania. Un campione accettabile è uno dei tipi di dati che gli servono, insieme ai campioni di basilisco e iena. Quando la raccolta è completa, il kit torna a Segachiodi, che può rimuoverne la fonte di energia."}},faq={{q="Cos'è un campione accettabile di scorpide?",a="Un campione accettabile di scorpide è un dato raccolto da uno scorpide con il Field Testing Kit a Tanaris.",al={"campione di scorpide","scorpide accettabile","dati sugli scorpidi"}},{q="Chi ha bisogno dei campioni di scorpide?",a="Capo Ingegnere Segachiodi di Meccania ha bisogno dei campioni di scorpide, insieme a quelli di basilisco e iena.",al={"chi vuole i campioni","campioni di segachiodi","chi ha bisogno di dati sugli scorpidi"}},{q="A cosa serve il campione?",a="Il campione fornisce dati per lo studio sul campo di Capo Ingegnere Segachiodi a Tanaris.",al={"perché raccogliere campioni di scorpide","test sugli scorpidi","a cosa servono i dati"}},{q="Che cosa succede al kit dopo il campionamento?",a="Riporta il Field Testing Kit a Capo Ingegnere Segachiodi a Meccania, così potrà rimuoverne la fonte di energia.",al={"riportare il kit","fonte di energia del kit","cosa fare con il field testing kit"}}},fp="25,163,11.289.0,37.99.0,30.106.0,28.82.0,39.111.0"}
