P.entries["item:aged-gorilla-sinew"] = {n="Aged Gorilla Sinew",s="Il tendine di gorilla invecchiato si trova sugli Elder Mistvale Gorillas a est della Baia del Bottino, nella Valle di Rovotorto. Al Chiaroveggente Mok'thardin ne serve uno come legame magico per il suo lavoro.",h="Il tendine di gorilla invecchiato si trova sugli Elder Mistvale Gorillas a est della Baia del Bottino, nella...",kw={"aged gorilla sinew","baia del bottino","elder mistvale gorilla","chiaroveggente mok'thardin","tendine di gorilla","legame magico","vallebruma","valle di rovotorto"},sec={{t="Un legame magico",b="A est della Baia del Bottino, gli Elder Mistvale Gorillas si procurano cibo nella giungla. Al Chiaroveggente Mok'thardin serve un tendine invecchiato di uno di loro per tenere ferme piume, artigli e una zanna incontaminata. Il tendine dev'essere perfetto, quindi trovarne uno potrebbe richiedere pazienza."}},faq={{q="Dove posso trovare Aged Gorilla Sinew?",a="Gli Elder Mistvale Gorillas si procurano cibo a est della Baia del Bottino, nella Valle di Rovotorto, e uno di loro potrebbe fornire un tendine invecchiato.",al={"posizione del tendine invecchiato","dove trovare il tendine di gorilla","dove si trova il tendine"}},{q="A chi serve il tendine?",a="Al Chiaroveggente Mok'thardin, a Grom'gol, serve Aged Gorilla Sinew come legame magico.",al={"chi vuole il tendine","mok'thardin tendine","cosa serve al chiaroveggente"}},{q="A cosa serve il tendine?",a="Mok'thardin usa il tendine per tenere ferme piume, artigli e una zanna incontaminata.",al={"perché il tendine","a cosa serve aged gorilla sinew","legame magico"}},{q="Perché il tendine deve essere perfetto?",a="A Mok'thardin serve un tendine perfetto per il suo legame magico.",al={"perché il tendine deve essere perfetto","tendine buono","perché invecchiato"}}},fp="18,159,16.238.0,36.104.0,20.81.0,27.81.0,30.60.0"}
P.entries["item:aged-kodo-hide"] = {n="Aged Kodo Hide",s="Aged Kodo Hide si ricava dai kodo anziani di Desolanda. Kreldig Ungor ha bisogno di tre Aged Kodo Hide per Reagents for Reclaimers Inc., oltre al veleno di Scorpashi.",h="Aged Kodo Hide si ricava dai kodo anziani di Desolanda.",kw={"kodo anziano","aged kodo hide","desolanda","cimitero dei kodo","kreldig ungor","leftwitch","reclaimers inc.","veleno di scorpashi"},ang={["class:Mage"]="Da mago, potresti riconoscere Aged Kodo Hide tra i reagenti nell'elenco di Leftwitch per Reagents for Reclaimers Inc."},sec={{t="Un reagente per i kodo",b="Kreldig Ungor ha bisogno di tre Aged Kodo Hides a Desolanda, oltre a sette fiale di veleno di Scorpashi. La pelle deve provenire da un kodo anziano; i kodo morenti e antichi non forniscono questo reagente."}},faq={{q="Da dove provengono gli Aged Kodo Hide?",a="Gli Aged Kodo Hide provengono dai kodo anziani di Desolanda.",al={"fonte di aged kodo hide","dove trovare la pelle","pelle di kodo"}},{q="Chi ha bisogno degli Aged Kodo Hide?",a="Kreldig Ungor ha bisogno di tre Aged Kodo Hides per Reagents for Reclaimers Inc.",al={"chi vuole la pelle","reagenti di kreldig","pelle per reclaimers inc."}},{q="Qualsiasi kodo può fornire la pelle?",a="No. La pelle deve provenire da un kodo anziano, non da un kodo morente o antico.",al={"quale kodo","pelle di kodo morente","pelle di kodo antico"}},{q="Di cos'altro ha bisogno Kreldig?",a="Kreldig ha bisogno anche di sette fiale di Scorpashi Venom.",al={"altri reagenti","veleno di scorpashi","cos'altro serve a kreldig"}}},fp="14,129,14.187.0,35.49.0,25.74.0,31.70.0,28.50.0"}
