P.entries["item:akiris-reed"] = {n="Akiris Reed",s="Lungo le spiagge di Capo di Rovotorto, i naga raccolgono Akiris Reed, una preziosa pianta oceanica. Corsaro Bloads a Baia del Bottino paga bene per i mazzi.",h="Lungo le spiagge di Capo di Rovotorto, i naga raccolgono Akiris Reed, una preziosa pianta oceanica.",kw={"akiris","akiris reed","baia del bottino","capo di rovotorto","groy","naga","corsaro bloads"},sec={{t="Canne della costa",b="Corsaro Bloads a Baia del Bottino paga per i mazzi di Akiris Reed raccolti lungo la spiaggia settentrionale. I naga chiamano akiris la canna oceanica, e Bloads dice che il suo amico Groy si guadagna da vivere vendendola. Bloads non sa a cosa serva la canna a Groy; per lui bastano dieci steli per avviare un commercio redditizio."}},faq={{q="Che cos'è Akiris Reed?",a="Akiris Reed è una preziosa canna oceanica raccolta dai naga lungo le spiagge di Capo di Rovotorto.",al={"akiris reed","pianta akiris","canna oceanica"}},{q="Chi vuole Akiris Reed?",a="Corsaro Bloads a Baia del Bottino paga i mazzi di Akiris Reed per conto del suo amico Groy.",al={"chi compra akiris","acquirente akiris reed","bloads canna"}},{q="A cosa serve la canna a Groy?",a="Corsaro Bloads dice di non sapere a cosa serva Akiris Reed a Groy; sa solo che Groy la vende ricavandone un profitto.",al={"a cosa serve akiris","uso akiris groy","usi della canna"}},{q="Dove posso trovare Akiris Reed?",a="I naga raccolgono Akiris Reed lungo le spiagge a nord di Baia del Bottino, a Capo di Rovotorto.",al={"posizione akiris","dove trovare la canna","spiaggia naga"}}},fp="11,161,19.308.0,20.96.0,22.91.0,32.111.0,29.90.0"}
