P.entries["item:ambassador-infernus-bracer"] = {n="Bracciale dell'Ambasciatore Infernus",s="Nelle Maleterre, il Consigliere Belgrum ti chiede di riportare una prova della sconfitta di Ambassador Infernus. Spera di poter inviare aiuti agli scavi in difficoltà a Uldaman.",h="Nelle Maleterre, il Consigliere Belgrum ti chiede di riportare una prova della sconfitta di Ambassador...",kw={"consigliere belgrum","ambassador infernus","fortezza di angor","maleterre","bracciale","bracciale infernus","forgiardente","ragnaros","shadowforge","uldaman"},ang={["race:Dwarf"]="Da nano, porti la prova di una minaccia per Forgiardente: la ricerca di Shadowforge a Uldaman è già costata la vita a molti nani."},sec={{t="Prova da Angor",b="Karnik lo Storico ti manda alla Fortezza di Angor, nelle Maleterre, per sconfiggere Ambassador Infernus. Ragnaros ha mandato l'ambasciatore a sorvegliare la ricerca di Shadowforge di artefatti perduti a Uldaman. Gli scavi sono già costati molte vite e Karnik teme che quegli artefatti possano minacciare Forgiardente. Riporta il bracciale al Consigliere Belgrum come prova, così potrà inviare aiuti al sito."}},faq={{q="Cos'è il Bracciale dell'Ambasciatore Infernus?",a="Il Bracciale dell'Ambasciatore Infernus è la prova della sconfitta dell'ambasciatore, da riportare al Consigliere Belgrum a Forgiardente.",al={"bracciale infernus","bracciale dell'ambasciatore","cos'è il bracciale"}},{q="Dove trovo il bracciale?",a="Il bracciale si ottiene da Ambassador Infernus alla Fortezza di Angor, nelle Maleterre.",al={"posizione del bracciale","dov'è infernus","ottenere il bracciale"}},{q="Chi vuole il bracciale?",a="Karnik lo Storico ti chiede di portare il bracciale al Consigliere Belgrum a Forgiardente come prova della sconfitta di Ambassador Infernus.",al={"chi vuole il bracciale","bracciale per belgrum","consegnare il bracciale"}},{q="Perché Ambassador Infernus si trova nelle Maleterre?",a="Ragnaros ha mandato Ambassador Infernus a sorvegliare la ricerca di Shadowforge di artefatti perduti a Uldaman.",al={"perché infernus è qui","infernus nelle maleterre","cosa sta facendo"}},{q="Perché Forgiardente vuole sconfiggere l'ambasciatore?",a="Gli scavi di Shadowforge hanno causato molte vittime e Karnik lo Storico teme che gli artefatti recuperati possano essere usati contro Forgiardente.",al={"perché uccidere infernus","minaccia per forgiardente","qual è il pericolo"}},{q="Cosa succede dopo che l'ho portato a Belgrum?",a="Belgrum ti ringrazia e dice che manderà notizie a Karnik lo Storico e organizzerà aiuti per il sito di scavi nelle Maleterre.",al={"dopo il bracciale","consegna a belgrum","e poi"}}},fp="27,154,16.375.0,36.110.0,27.76.0,21.118.0,43.96.0,48.138.0,41.115.1"}
