P.entries["item:ancient-egg"] = {n="Uovo Antico",s="L'Uovo Antico è una reliquia troll nascosta a Jintha'alor, negli Entroterre. Yeh'kinya la cerca perché la Prophecy of Mosh'aru dice che può contenere l'essenza di Hakkar.",h="L'Uovo Antico è una reliquia troll nascosta a Jintha'alor, negli Entroterre.",kw={"uovo antico","hakkar","entroterre","jintha'alor","mosh'aru","reliquia troll","yeh'kinya"},ang={["race:Troll"]="Da troll, l'Uovo Antico ti ricorda i vasti imperi del tuo popolo e il potere racchiuso nelle sue antiche reliquie."},sec={{t="Una reliquia a Jintha'alor",b="Nel cuore della città troll di Jintha'alor, l'Uovo Antico giace in una grotta oltre l'anfiteatro. Yeh'kinya lo cerca a Tanaris, dove studia la Prophecy of Mosh'aru. La profezia indica l'uovo come ricettacolo per l'essenza di Hakkar. Yeh'kinya teme che il destino del mondo possa dipendere da esso."}},faq={{q="Che cos'è l'Uovo Antico?",a="L'Uovo Antico è una reliquia troll risalente all'epoca dei grandi imperi troll. La Prophecy of Mosh'aru dice che può contenere l'essenza di Hakkar.",al={"uovo antico","quale uovo","uovo troll"}},{q="Dov'è l'Uovo Antico?",a="L'Uovo Antico giace in una grotta nelle profondità di Jintha'alor, dietro l'anfiteatro in cima alla città, negli Entroterre.",al={"posizione dell'uovo","dov'è l'uovo","uovo di jintha'alor"}},{q="Chi vuole l'Uovo Antico?",a="Yeh'kinya, a Tanaris, cerca l'Uovo Antico per ciò che la Prophecy of Mosh'aru dice che può fare.",al={"uovo di yeh'kinya","chi lo vuole","portare l'uovo a"}},{q="Perché Yeh'kinya lo vuole?",a="Yeh'kinya crede che l'Uovo Antico possa essere l'unico modo per proteggere il mondo dal male di Hakkar.",al={"perché l'uovo","uovo di hakkar","uovo della profezia"}}},fp="11,164,22.282.0,24.128.0,25.120.0,26.99.0,27.97.0"}
