P.entries["item:atal-ai-artifact"] = {n="Atal'ai Artifact",s="Gli Atal'ai Artifacts sono sparsi nel Bacino delle Lacrime, attorno al Sunken Temple di Atal'Hakkar. Fel'zerul li cerca per scoprire quali magie praticassero lì gli Atal'ai.",h="Gli Atal'ai Artifacts sono sparsi nel Bacino delle Lacrime, attorno al Sunken Temple di Atal'Hakkar.",kw={"atal'ai","atal'ai artifact","fel'zerul","bacino delle lacrime","pietrachiusa","palude del dolore","tempio di atal'hakkar","magia dei troll"},ang={["faction:Horde"]="Come membro dell'Orda, Fel'zerul ti chiede di aiutarlo a indagare sul tempio sommerso e a studiare la potente magia degli Atal'ai."},sec={{t="Reliquie nel Bacino",b="Acque oscure circondano il Sunken Temple di Atal'Hakkar, sommerso nella Palude del Dolore. Gli Atal'ai Artifacts riposano nel Bacino delle Lacrime, dove Fel'zerul di Pietrachiusa li cerca. Gli Atal'ai erano incantatori oscuri, e la magia praticata nel loro tempio era potente. Queste reliquie potrebbero aiutare Fel'zerul a capire cosa cercassero di ottenere i troll."}},faq={{q="Dove si trovano gli Atal'ai Artifacts?",a="Gli Atal'ai Artifacts si trovano nel Bacino delle Lacrime, attorno al Sunken Temple di Atal'Hakkar, nella Palude del Dolore.",al={"dove trovare gli artefatti","luogo degli artefatti","artefatti nel bacino delle lacrime"}},{q="Chi cerca gli artefatti?",a="Fel'zerul, a Pietrachiusa, cerca gli Atal'ai Artifacts per studiare la magia usata dagli Atal'ai.",al={"chi li cerca","artefatti di fel'zerul","chi vuole l'artefatto"}},{q="A cosa servono gli artefatti?",a="Fel'zerul spera che gli artefatti lo aiutino a capire cosa cercassero di ottenere i troll Atal'ai con la loro potente magia.",al={"scopo degli artefatti","perché raccogliere gli artefatti","cosa rivelano"}},{q="Chi erano gli Atal'ai?",a="Gli Atal'ai erano una tribù di troll nota per praticare magie proibite.",al={"troll atal'ai","tribù atal'ai","troll incantatori oscuri"}}},fp="16,163,18.327.0,32.107.0,24.91.0,27.131.0,21.72.0"}
P.entries["item:atal-ai-tablet-fragment"] = {n="Frammento di Tavoletta degli Atal'ai",s="Il Frammento di Tavoletta degli Atal'ai è un ricordo troll che Rhapsody Shindigger ha trovato vicino al Sunken Temple. Brohann Panciapiena lo considera un artefatto degli Atal'ai.",h="Il Frammento di Tavoletta degli Atal'ai è un ricordo troll che Rhapsody Shindigger ha trovato vicino al...",kw={"atal'ai","frammento di tavoletta degli atal'ai","brohann panciapiena","frammento","rhapsody shindigger","sunken temple","tavoletta","troll"},sec={{t="Un ricordo troll",b="Rhapsody Shindigger ha trovato il Frammento di Tavoletta degli Atal'ai dopo essere caduto in acqua vicino al Sunken Temple. Dice che lì era circondato da troll inquietanti e che è fuggito a nuoto con questo frammento. Te lo affida perché tu lo consegni a Brohann Panciapiena a Roccavento."}},faq={{q="Che cos'è il Frammento di Tavoletta degli Atal'ai?",a="È un ricordo troll che Rhapsody Shindigger ha raccolto vicino al Sunken Temple.",al={"tavoletta degli atal'ai","frammento di tavoletta","frammento troll"}},{q="Dove l'ha trovato Rhapsody?",a="Rhapsody dice di aver trovato il frammento in acqua vicino al Sunken Temple, circondato dai troll.",al={"da dove viene il frammento","tavoletta di rhapsody","ricordo del tempio"}},{q="A chi devo consegnare il frammento?",a="Porta il Frammento di Tavoletta degli Atal'ai a Brohann Panciapiena a Roccavento.",al={"chi lo vuole","tavoletta di brohann","dove consegnare il frammento"}},{q="Perché lo vuole Brohann?",a="Brohann riconosce il frammento come un artefatto degli Atal'ai e dice che è una bella scoperta.",al={"perché brohann lo vuole","quanto vale","artefatto degli atal'ai"}}},fp="23,147,16.240.0,36.79.0,27.92.0,34.68.0,25.81.0"}
