P.entries["item:bag-of-empty-ooze-containers"] = {n="Sacca di Contenitori per Melme Vuoti",s="A Forgiardente, Laris Perdiruote fornisce barattoli vuoti per il suo studio sulle melme di Azeroth. Servono a contenere melma pulita raccolta nelle terre selvagge.",h="A Forgiardente, Laris Perdiruote fornisce barattoli vuoti per il suo studio sulle melme di Azeroth.",kw={"sacca di contenitori per melme vuoti","contenitore di campioni puri vuoto","forgiardente","laris perdiruote","contenitori per melme","contenitore di campioni puri","melma"},ang={["faction:Alliance"]="Per chi viaggia con l'Alleanza, è l'occasione di aiutare Laris Perdiruote nelle sue ricerche ecologiche a Forgiardente, portandogli campioni da luoghi selvaggi come il Cratere di Un'Goro.",["race:Gnome"]="Per chi è gnomo, questi barattoli robusti e resistenti agli agenti chimici sono un esempio di ingegno: permettono ai ricercatori di trasportare in sicurezza campioni di fauna pericolosi e corrosivi."},sec={{t="Attrezzatura per la ricerca sul campo",b="Laris Perdiruote studia la strana biologia delle melme di Azeroth. Ha scoperto che assorbono rapidamente la corruzione che le circonda, compresi i residui contaminati del Vilbosco. Così ha commissionato barattoli robusti, capaci di contenere esemplari acidi senza danneggiarli. La sacca contiene abbastanza barattoli per raccogliere melma pulita nelle regioni selvagge, soprattutto nel Cratere di Un'Goro, dove antiche melme glutinose vivono lontano dalla contaminazione demoniaca."}},faq={{q="Che cosa contiene la Sacca di Contenitori per Melme Vuoti?",a="La sacca contiene dieci Contenitori di Campioni Puri Vuoti. Il loro vetro può contenere melma caustica senza danneggiare o contaminare il campione.",al={"cosa c'è nella sacca","contenuto della sacca","contenuto dei contenitori per melme"}},{q="Chi ha fornito questi contenitori?",a="Li fornisce Laris Perdiruote, un ricercatore gnomo del Salone degli Esploratori di Forgiardente, che studia come le melme si adattano all'ambiente.",al={"chi dà la sacca per melme","sacca di laris perdiruote","chi dà la sacca di contenitori per melme vuoti"}},{q="Che tipo di melme devono raccogliere questi barattoli?",a="I barattoli sono destinati a melma pura e incontaminata. Puoi raccogliere melma intatta dalle melme glutinose del Cratere di Un'Goro, a differenza degli esemplari corrotti del Vilbosco.",al={"quale melma va nei barattoli","obiettivo del contenitore di campioni puri","dove riempire i barattoli"}},{q="Perché Laris ha bisogno di campioni di melma puri?",a="Laris ha bisogno di melma pura per studiare come le melme assorbono le qualità del loro ambiente. Così può confrontare un esemplare incontaminato con le melme inquinate delle regioni corrotte.",al={"perché raccogliere melma pura","obiettivo della ricerca di perdiruote","perché melme pure"}}},fx={["9a2213f5"]={q="Che cos'è la Sacca di Contenitori per Melme Vuoti?",a="Questa sacca è un kit di attrezzatura specializzata da campo, che ti consegna Laris Perdiruote a Forgiardente. Contiene dieci barattoli per campioni vuoti, pensati per conservare e trasportare in sicurezza fino alla sua officina esemplari instabili di melma, senza perdite e senza contaminarne il contenuto.",al={"sacca di contenitori per melme vuoti","che cosa sono i contenitori per melme","sacca per melme di laris"}}},fp="28,142,24.407.0,48.119.0,30.148.0,51.161.0,38.165.0"}
P.entries["item:bag-of-water-elemental-bracers"] = {n="Bag of Water Elemental Bracers",s="Una borsa di bracciali di elementali dell'acqua viene portata all'Arcimago Ansirem Tessiruna perché li studi. I loro residui magici potrebbero aiutarlo a esaminare la maledizione della Pietra delle Maree.",h="Una borsa di bracciali di elementali dell'acqua viene portata all'Arcimago Ansirem Tessiruna perché li studi.",kw={"arcimago ansirem tessiruna","borsa di bracciali di elementali dell'acqua","maledizione","dalaran","impero gurubashi","residui magici","pietra delle maree","bracciali di elementali dell'acqua"},ang={["class:Mage"]="Da mago, porti ad Ansirem un enigma magico: i residui su un bracciale di un elementale dell'acqua potrebbero aiutarlo a studiare la maledizione della Pietra delle Maree."},sec={{t="Lo studio di un mago",b="A Dalaran, all'Arcimago Ansirem Tessiruna è stato chiesto di esaminare i bracciali di elementali dell'acqua. Almeno uno reca residui magici, che secondo lui potrebbero far luce sulla maledizione della Pietra delle Maree. Ansirem conosce le leggende dell'Impero Gurubashi e ha scritto un tomo sull'argomento. Ora rivolge la sua attenzione ai bracciali."}},faq={{q="Cosa c'è nella borsa?",a="La borsa contiene bracciali di elementali dell'acqua che l'Arcimago Ansirem Tessiruna deve esaminare.",al={"contenuto della borsa","borsa di bracciali","quali bracciali"}},{q="Chi dovrebbe studiare i bracciali?",a="All'Arcimago Ansirem Tessiruna è stato chiesto di studiare i bracciali di elementali dell'acqua a Dalaran.",al={"chi li studia","bracciali ansirem","mago a dalaran"}},{q="Perché Ansirem vuole i bracciali?",a="Almeno un bracciale reca residui magici che Ansirem può analizzare per trovare indizi sulla maledizione della Pietra delle Maree.",al={"perché i bracciali","maledizione dei bracciali","maledizione della pietra"}},{q="Cosa sa Ansirem della Pietra?",a="Ansirem dice di sapere parecchio sulla Pietra delle Maree e di aver scritto un tomo sulle leggende dell'Impero Gurubashi.",al={"cosa sa ansirem della pietra","storia della pietra delle maree","tomo dei gurubashi"}}},fp="30,161,16.332.0,19.81.0,37.85.0,34.115.0,39.124.0"}
P.entries["item:balia-mah-trophy"] = {n="Balia'mah Trophy",s="Il Balia'mah Trophy è un teschio trofeo dei Fendicranio, prelevato dalle rovine nella Valle di Rovotorto. Nezzliok lo richiede insieme ad altri due trofei presso il Bubbling Cauldron, al Forte di Grom'gol.",h="Il Balia'mah Trophy è un teschio trofeo dei Fendicranio, prelevato dalle rovine nella Valle di Rovotorto.",kw={"balia'mah","rovine di balia'mah","balia'mah trophy","grom'gol","nezzliok","fendicranio","teschio trofeo","ziata'jai","zul'mamwe"},sec={{t="Un trofeo dei Fendicranio",b="Tra le rovine di Balia'mah nella Valle di Rovotorto, i Fendicranio tengono i teschi trofeo in un mucchio. Un teschio di quel mucchio è il Balia'mah Trophy, richiesto insieme ai trofei di Ziata'jai e Zul'Mamwe."}},faq={{q="Cos'è il Balia'mah Trophy?",a="Il Balia'mah Trophy è un teschio prelevato dal mucchio di teschi trofeo dei Fendicranio presso le Rovine di Balia'mah, nella Valle di Rovotorto.",al={"balia'mah trophy","teschio di balia'mah","teschio trofeo"}},{q="Chi vuole il Balia'mah Trophy?",a="Lo stregone defunto Nezzliok richiede il Balia'mah Trophy insieme ai trofei di Ziata'jai e Zul'Mamwe.",al={"chi vuole questo teschio","trofeo di nezzliok","trofeo per nezzliok"}},{q="Da dove viene il Balia'mah Trophy?",a="Il Balia'mah Trophy viene dal mucchio di teschi trofeo presso le Rovine di Balia'mah, nella Valle di Rovotorto.",al={"dove trovare balia'mah","teschio rovine di balia'mah","trofeo dei fendicranio"}},{q="Dove vanno i tre trofei?",a="Nezzliok chiede che i trofei di Balia'mah, Ziata'jai e Zul'Mamwe siano deposti presso il Bubbling Cauldron, al Forte di Grom'gol.",al={"dove deporre i teschi","trofei al bubbling cauldron","tre teschi"}}},fp="16,194,22.201.0,29.114.0,31.110.1,35.99.0,31.124.0"}
