P.entries["item:befouled-bloodstone-orb"] = {n="Sfera Infame di Sanguinite",s="La Sfera Infame di Sanguinite è una reliquia magica custodita da uno stregone nel Forte di Stromgarde. Tor'gan, a Requie del Martello, la cerca per porre fine al suo potere sulla regione.",h="La Sfera Infame di Sanguinite è una reliquia magica custodita da uno stregone nel Forte di Stromgarde.",kw={"altopiani d'arathi","sfera infame di sanguinite","sfera di sanguinite","demoni","foul magics","marez cowl","forte di stromgarde","tor'gan","stregone"},ang={["class:Warlock"]="Da stregone, conosci il pericolo di una reliquia usata per evocare demoni. Tor'gan vuole distruggere la sfera prima che il suo potere contamini ancora gli Altopiani d'Arathi."},sec={{t="Una reliquia contaminata",b="Tor'gan teme che uno stregone nel Forte di Stromgarde stia usando una reliquia magica per evocare demoni. Cerca la Sfera Infame di Sanguinite per distruggerne il potere, prima che contamini ancora gli Altopiani d'Arathi."}},faq={{q="Cos'è la Sfera Infame di Sanguinite?",a="La Sfera Infame di Sanguinite è una reliquia magica custodita da Marez Cowl, uno stregone nel Forte di Stromgarde.",al={"sfera di sanguinite","sfera infame"}},{q="Chi possiede la sfera?",a="Marez Cowl, uno stregone nel Forte di Stromgarde, custodisce la Sfera Infame di Sanguinite.",al={"sfera di marez","chi possiede la sanguinite"}},{q="Perché Tor'gan la vuole?",a="Tor'gan vuole la sfera per distruggerla e impedire che il suo potere contamini gli Altopiani d'Arathi.",al={"sfera di tor'gan","perché recuperare la sfera"}},{q="A cosa serve la sfera?",a="Tor'gan crede che uno stregone abbia usato la sfera per evocare demoni in gran numero.",al={"sfera e demoni","magia della sanguinite"}},{q="Dov'è la sfera?",a="Marez Cowl custodisce la sfera tra le mura del Forte di Stromgarde, negli Altopiani d'Arathi.",al={"posizione della sfera","sanguinite di stromgarde"}}},fp="23,147,15.210.0,36.96.0,16.80.0,25.93.0,25.78.0,17.81.0"}
