P.entries["item:blacklash-s-bindings"] = {n="Bracciali di Codanera",s="I Bracciali di Codanera sono ricercati da chi vuole porre fine alla minaccia dei draghi della Piana di Lethlor.",h="I Bracciali di Codanera sono ricercati da chi vuole porre fine alla minaccia dei draghi della Piana di...",kw={"maleterre","drago nero","blacklash","bracciali di codanera","piana di lethlor","pietrerune","seal of the earth","simbolo della terra"},sec={{t="La prova di un uccisore di draghi",b="Nella Piana di Lethlor, i Bracciali di Codanera segnano la fine della prigionia di un drago nero e della minaccia che ne è seguita. Il sigillo che imprigiona Blacklash e Hematus dipende da tre pietrerune prese dai pilastri vicini, contrassegnati dal Simbolo della Terra. Una volta infranto il sigillo, entrambi i draghi vengono liberati. I loro bracciali vengono poi riportati come prova della morte di Blacklash."}},faq={{q="Cosa sono i Bracciali di Codanera?",a="I Bracciali di Codanera sono un ricordo preso dal drago nero dopo la sua morte nella Piana di Lethlor.",al={"bracciali di codanera","cos'è the binding","roba di blacklash"}},{q="Chi è Blacklash?",a="Blacklash è un drago nero imprigionato con Hematus sotto il Seal of the Earth nella Piana di Lethlor.",al={"storia di blacklash","chi è blacklash","drago nero blacklash"}},{q="Da dove vengono i bracciali?",a="I bracciali provengono da Blacklash a Maleterre.",al={"provenienza dei bracciali","bottino di blacklash","ottenere i bracciali"}},{q="Perché si cercano i bracciali?",a="Chi vuole porre fine alla minaccia di Blacklash e Hematus chiede i bracciali come prova della morte di Blacklash.",al={"perché servono i bracciali","a cosa servono i bracciali","oggetto missione blacklash"}},{q="Come sono stati liberati Blacklash e Hematus?",a="Il Simbolo della Terra consente a chi lo porta di prendere tre pietrerune dai pilastri della Piana di Lethlor. Posandole nel Seal of the Earth, si liberano entrambi i draghi.",al={"liberare i draghi","come infrangere il sigillo","pietrerune e sigillo"}}},fp="20,104,21.351.0,30.97.1,17.99.0,32.49.1,28.112.1,37.152.1"}
