P.entries["item:bloodsail-charts"] = {n="Piani dei Velerosse",s="I Piani dei Velerosse vengono sottratti al campo dei Bucanieri Velerosse sulle Rive Selvagge. Il Contrammiraglio Corno Marino vuole che li porti a Baia del Bottino insieme agli Ordini dei Velerosse, così potrà scoprire cosa stanno pianificando i pirati.",h="I Piani dei Velerosse vengono sottratti al campo dei Bucanieri Velerosse sulle Rive Selvagge.",kw={"bucanieri velerosse","piani dei velerosse","ordini dei velerosse","baia del bottino","contrammiraglio corno marino","rive selvagge"},sec={{t="Carte dalle Rive",b="Il Contrammiraglio Corno Marino ti manda al campo dei Bucanieri Velerosse sulle Rive Selvagge. Vuole che riporti a Baia del Bottino le loro carte e gli ordini scritti. Dice che, con entrambi, la flotta potrà scoprire il piano dei Velerosse."}},faq={{q="Dove si trovano i Piani dei Velerosse?",a="I Piani dei Velerosse si trovano nel campo dei Bucanieri Velerosse sulle Rive Selvagge, nella Valle di Rovotorto.",al={"posizione dei piani dei velerosse","dove sono i piani","piani rive selvagge"}},{q="Chi vuole le carte?",a="Il Contrammiraglio Corno Marino, a Baia del Bottino, vuole i Piani dei Velerosse e gli Ordini dei Velerosse.",al={"chi vuole i piani","piani corno marino","piani contrammiraglio"}},{q="Perché Corno Marino ne ha bisogno?",a="Corno Marino vuole le carte e gli ordini scritti per scoprire cosa stanno pianificando i Bucanieri Velerosse.",al={"perché i piani","a cosa servono i piani","piano dei velerosse"}},{q="Cosa devo riportare insieme alle carte?",a="Porta gli Ordini dei Velerosse insieme ai Piani dei Velerosse dal Contrammiraglio Corno Marino a Baia del Bottino.",al={"piani e cos'altro","anche gli ordini dei velerosse","riportare gli ordini"}}},fp="16,195,21.224.0,31.97.0,21.82.0,27.96.0,41.90.0"}
P.entries["item:bloodsail-orders-classic"] = {n="Ordini dei Velerosse",s="Gli Ordini dei Velerosse sono istruzioni scritte custodite dai Bucanieri Velerosse sulle Rive Selvagge. Il Contrammiraglio Corno Marino, a Baia del Bottino, li cerca per scoprire i piani dei bucanieri.",h="Gli Ordini dei Velerosse sono istruzioni scritte custodite dai Bucanieri Velerosse sulle Rive Selvagge.",kw={"velerosse","ordini dei velerosse","baia del bottino","bucanieri","contrammiraglio corno marino","valle di rovotorto","rive selvagge","ordini scritti"},sec={{t="Ordini dalla costa",b="Sulle Rive Selvagge, i Bucanieri Velerosse custodiscono ordini scritti nel loro avamposto di comando meridionale. Il Contrammiraglio Corno Marino, a Baia del Bottino, vuole che gli vengano riportate quelle istruzioni insieme ai Piani dei Velerosse. Vuole scoprire cosa stanno pianificando i bucanieri nei pressi del promontorio."}},faq={{q="Cosa sono gli Ordini dei Velerosse?",a="Sono istruzioni scritte custodite dai Bucanieri Velerosse nel loro accampamento sulle Rive Selvagge.",al={"ordini dei velerosse","oggetto ordini"}},{q="Dove si trovano gli Ordini dei Velerosse?",a="Gli Ordini dei Velerosse sono custoditi nell'accampamento dei Bucanieri Velerosse sulle Rive Selvagge, nella Valle di Rovotorto.",al={"dove sono gli ordini","ordini rive selvagge"}},{q="Chi vuole gli ordini?",a="Il Contrammiraglio Corno Marino, a Baia del Bottino, vuole che gli vengano riportati gli Ordini dei Velerosse.",al={"chi vuole gli ordini","ordini corno marino"}},{q="Perché il Contrammiraglio Corno Marino li vuole?",a="Il Contrammiraglio Corno Marino vuole scoprire i piani dei Bucanieri Velerosse studiandone gli ordini scritti e le carte.",al={"perché gli ordini","cosa cerca corno marino"}},{q="Cos'altro dovrei riportare insieme agli ordini?",a="Il Contrammiraglio Corno Marino vuole anche i Piani dei Velerosse dall'accampamento sulle Rive Selvagge.",al={"ordini e carte","cos'altro riportare"}}},fp="16,181,21.260.0,30.94.0,31.110.0,21.81.0,40.123.0,41.84.0"}
P.entries["item:bloodscalp-tusk"] = {n="Bloodscalp Tusk",s="Un Bloodscalp Tusk si ricava da un troll Bloodscalp nel nord della Valle di Rovotorto. Nimboya, al Forte di Grom'gol, chiede le zanne come prova che puoi aiutarlo a cercare Yenniku.",h="Un Bloodscalp Tusk si ricava da un troll Bloodscalp nel nord della Valle di Rovotorto.",kw={"bloodscalp","bloodscalp tusk","grom'gol","nimboya","rovotorto","troll","yenniku"},ang={["faction:Horde"]="Come membro dell'Orda, puoi aiutare Nimboya, un Puntascura mandato da Orgrimmar a cercare il figlio scomparso del suo capo.",["race:Troll"]="Se sei un troll, puoi comprendere il dolore per la perdita di Yenniku: è un bambino Puntascura separato dalla sua gente."},sec={{t="Una prova di caccia",b="Al Forte di Grom'gol, Nimboya ti chiede di portargli nove Bloodscalp Tusk. Deve sapere che sai dare la caccia alla tribù prima di fidarsi di te per aiutarlo a trovare Yenniku, il figlio minore del suo capo. Le zanne dimostrano la tua forza."}},faq={{q="Cos'è un Bloodscalp Tusk?",a="Un Bloodscalp Tusk proviene da un troll della tribù Bloodscalp nella Valle di Rovotorto.",al={"bloodscalp tusk","che zanne sono"}},{q="Chi vuole i Bloodscalp Tusk?",a="Nimboya, al Forte di Grom'gol, ti chiede di portargli nove Bloodscalp Tusk.",al={"chi vuole le zanne","zanne di nimboya"}},{q="Perché Nimboya ha bisogno delle zanne?",a="Nimboya vuole le zanne come prova che sei abbastanza forte da aiutarlo a cercare Yenniku.",al={"perché le zanne","motivo delle zanne"}},{q="Chi è Yenniku?",a="Yenniku è il figlio minore del capo di Nimboya, e Nimboya crede che la tribù Bloodscalp lo abbia preso.",al={"chi è yenniku","figlio del capo di nimboya"}},{q="Dove trovo i troll Bloodscalp?",a="La tribù Bloodscalp vive nel nord della Valle di Rovotorto.",al={"dove si trovano i bloodscalp","dove sono i bloodscalp"}}},fp="15,174,16.222.0,26.83.0,27.74.0,32.91.0,15.98.0,35.58.0"}
P.entries["item:bloodstone-choker"] = {n="Girocollo con Sanguinite",s="A Roccavento, il Girocollo con Sanguinite di Gakin il Vincolaombre lega il rito di uno stregone al vuoto. La sua apprendista ha rubato il talismano ed è fuggita presso la Fratellanza dei Defias.",h="A Roccavento, il Girocollo con Sanguinite di Gakin il Vincolaombre lega il rito di uno stregone al vuoto.",kw={"girocollo con sanguinite","defias","gakin il vincolaombre","surena caledon","il vincolo","agnello macellato","ombra del vuoto","stregone"},ang={["class:Warlock"]="Per chi è stregone dell'Alleanza, recuperare il Girocollo con Sanguinite segna il passaggio dagli incantesimi di base al comando di formidabili servitori demoniaci.",["faction:Alliance"]="La fuga di Surena Caledon nella Fratellanza dei Defias mostra che i fuorilegge di Elwynn cercano pericolose reliquie occulte per rafforzare la loro ribellione contro Roccavento."},sec={{t="Un catalizzatore rubato",b="Il Girocollo con Sanguinite apparteneva un tempo a Gakin il Vincolaombre, maestro di stregoni sotto l'Agnello Macellato di Roccavento. La sua apprendista Surena Caledon lo ha tradito e lo ha rubato. È fuggita nelle foreste di Elwynn e si è unita alla Fratellanza dei Defias, portando con sé il talismano incantato. Ora si trova al Campo di Zucche dei Pozzonero. Il girocollo va recuperato prima che i banditi ne usino il potere."},{t="Domare il Vuoto",b="Intagliato nella sanguinite, il girocollo crea un ponte tra il mondo mortale e le ombre tortuose della Distorsione Fatua. Nelle cripte sotto la taverna, Gakin ne incanala la magia nel cerchio di evocazione, e un'Ombra del Vuoto ostile risponde dal vuoto. Uno stregone deve affrontare la creatura furiosa in combattimento diretto e sottometterla impugnando il talismano. Solo così dimostra la forza di volontà necessaria per comandare un simile guardiano."}},faq={{q="Che cos'è il Girocollo con Sanguinite?",a="Gli stregoni usano il Girocollo con Sanguinite, una collana incantata di sanguinite, come catalizzatore rituale. La sua magia può squarciare la realtà ed evocare un'indisciplinata Ombra del Vuoto dalla Distorsione.",al={"girocollo con sanguinite","cos'è il girocollo","cosa fa il girocollo"}},{q="A chi apparteneva in origine il girocollo?",a="Il primo proprietario del girocollo è stato Gakin il Vincolaombre, che addestra gli stregoni in un seminterrato segreto sotto l'Agnello Macellato, nel Quartiere dei Maghi di Roccavento.",al={"di chi è il girocollo","girocollo di gakin","da dove viene il girocollo"}},{q="Perché il girocollo è stato rubato?",a="Surena Caledon ha rubato il girocollo al suo mentore, Gakin, ed è fuggita per unirsi alla Fratellanza dei Defias. Cercava il potere tra i banditi nascosti nella Foresta di Elwynn.",al={"chi l'ha rubato","perché surena l'ha rubato","girocollo di surena caledon"}},{q="Come si usa il girocollo nell'addestramento degli stregoni?",a="Uno stregone attiva il girocollo recuperato sul cerchio di evocazione nelle cripte sotto l'Agnello Macellato. Il girocollo fa apparire un'Ombra del Vuoto, che l'aspirante stregone deve sconfiggere e sottomettere per comandare il demone.",al={"come usare il girocollo","rituale dell'ombra del vuoto girocollo","il girocollo del vincolo"}}},fx={["9d3659ea"]={q="Perché il Girocollo con Sanguinite è richiesto?",a="Gakin il Vincolaombre tiene al Girocollo con Sanguinite perché è un potente catalizzatore magico, necessario per evocare e vincolare un'ombra del vuoto. Dopo che la sua ex apprendista Surena Caledon lo rubò per aiutare la Fratellanza dei Defias, Gakin vuole riaverlo per ristabilire la propria autorità arcana e mettere alla prova i nuovi stregoni nelle cripte sotto l'Agnello Macellato.",al={"perché vogliono il girocollo con sanguinite","chi vuole il girocollo con sanguinite","perché gakin vuole il girocollo"}}},fp="17,164,16.382.1,15.394.0,30.174.0,32.144.0,26.157.0,43.209.0"}
P.entries["item:bloody-bone-necklace"] = {n="Bloody Bone Necklace",s="Una Bloody Bone Necklace è un trofeo sottratto a un troll Bloodscalp nella Valle di Rovotorto. Kin'weelay, al Forte di Grom'gol, usa le collane in un rituale contro i nemici della sua tribù.",h="Una Bloody Bone Necklace è un trofeo sottratto a un troll Bloodscalp nella Valle di Rovotorto.",kw={"bloodscalp","bloody bone necklace","bloody bone necklaces","grom'gol","kin'weelay","rovotorto","trofeo troll"},ang={["faction:Horde"]="In quanto membro dell'Orda, puoi aiutare Kin'weelay, un troll nell'accampamento dell'Orda a Grom'gol, a contrastare la tribù Bloodscalp.",["race:Troll"]="In quanto troll, puoi vedere Kin'weelay trasformare un trofeo della tribù Bloodscalp in un'arma rituale contro i suoi proprietari."},sec={{t="Un trofeo troll",b="Kin'weelay ti chiede di portare venticinque Bloody Bone Necklaces al Forte di Grom'gol. La tribù Bloodscalp vive a nord ed è nemica di Kin'weelay. Crede che sottrarre i loro trofei darà alla sua tribù potere su di loro."},{t="Il rito di Kin'weelay",b="Al Forte di Grom'gol, Kin'weelay fa bollire le collane e vi applica sanguisughe, riducendole in pasta. Dice che il rito indebolirà gli spiriti dei loro proprietari. In cambio di questo servizio, dice di saldare il suo debito con te."}},faq={{q="Cos'è una Bloody Bone Necklace?",a="Una Bloody Bone Necklace è un trofeo sottratto a un troll Bloodscalp nella Valle di Rovotorto.",al={"bloody bone necklace","collana d'ossa","trofeo bloodscalp"}},{q="Chi vuole le collane?",a="Kin'weelay, al Forte di Grom'gol, chiede venticinque Bloody Bone Necklaces.",al={"chi vuole queste collane","collana kin weelay","personaggio collane"}},{q="Da dove vengono le collane?",a="I troll Bloodscalp della Valle di Rovotorto indossano le Bloody Bone Necklaces.",al={"dove trovare collane","collane bloodscalp","origine collane"}},{q="Perché Kin'weelay le vuole?",a="Kin'weelay dice che sottrarre trofei alla tribù Bloodscalp dà alla sua tribù potere sui nemici.",al={"perché kin vuole le ossa","perché raccogliere collane","potere della tribù"}},{q="Cosa fa Kin'weelay con le collane?",a="Kin'weelay fa bollire le collane e vi applica sanguisughe, poi le riduce in pasta con un rito volto a indebolire gli spiriti dei loro proprietari.",al={"cosa succede alle collane","far bollire collane","rito delle collane"}},{q="Dov'è Kin'weelay?",a="Kin'weelay si trova al Forte di Grom'gol, nella Valle di Rovotorto.",al={"posizione kin weelay","personaggio gromgol","kin a gromgol"}}},fp="20,171,14.228.0,17.197.1,31.87.0,24.76.0,33.71.0,30.99.0,43.119.0,20.58.0"}
