P.entries["item:bonegrip-s-note"] = {n="Bonegrip's Note",s="A Forgiardente, Gerrig Morsaossa annota i tre cimeli di cui ha bisogno. La nota gli permette di tenerne i nomi lontani da orecchie indiscrete.",h="A Forgiardente, Gerrig Morsaossa annota i tre cimeli di cui ha bisogno.",kw={"nota di bonegrip","gerrig morsaossa","artiglio di dagun","forgiardente","legacy heart","stella di xil'yeh","tre cimeli"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi raccogliere i cimeli indicati sulla nota di Gerrig e portarglieli a Forgiardente."},sec={{t="Nomi scritti",b="Gerrig Morsaossa ti chiede di portargli tre oggetti di potere a Forgiardente. Non ne pronuncerà i nomi, perché potrebbero esserci orecchie in ascolto. Invece, li scrive su Bonegrip's Note e te la consegna."}},faq={{q="Che cos'è Bonegrip's Note?",a="Bonegrip's Note è un elenco scritto dei tre oggetti di potere di cui Gerrig Morsaossa ha bisogno.",al={"nota di bonegrip","cos'è la nota","foglio di bonegrip"}},{q="Chi ha scritto la nota?",a="Gerrig Morsaossa ha scritto la nota per non dover pronunciare ad alta voce i nomi dei cimeli.",al={"chi ha scritto la nota","nota di gerrig","chi è morsaossa"}},{q="Di cosa ha bisogno Gerrig?",a="Gerrig ha bisogno della Stella di Xil'yeh, dell'Artiglio di Dagun e del Legacy Heart.",al={"quali oggetti sono elencati","tre cimeli","cosa c'è sulla nota"}},{q="Perché i nomi sono scritti?",a="Gerrig dice che potrebbero esserci orecchie in ascolto, quindi scrive i nomi dei cimeli invece di pronunciarli.",al={"perché non li dice","orecchie in ascolto","nomi segreti degli oggetti"}}},fp="15,124,13.203.0,24.80.0,19.85.0,22.74.0,31.96.0"}
