P.entries["item:bracers-of-rock-binding"] = {n="Bracers of Rock Binding",s="I Bracers of Rock Binding sono legacci di pietra ricavati da elementali di roccia superiori di Maleterre. Lotwil Veriatus ne ha bisogno per misurare la forza dei suoi ceppi.",h="I Bracers of Rock Binding sono legacci di pietra ricavati da elementali di roccia superiori di Maleterre.",kw={"maleterre","bracers of rock binding","elementale di roccia superiore","lotwil veriatus","bracciali di roccia","servo","ceppi"},sec={{t="Legacci di pietra",b="Lotwil Veriatus studia gli elementali di roccia superiori di Maleterre per i ceppi elementali che sta costruendo. Crede che i loro bracciali possano aiutarlo a valutare la forza dei suoi. Ne vuole cinque per averne di scorta per le sue ricerche, dato che il suo assistente Servo è noto per smarrire reagenti e appunti."}},faq={{q="Cosa sono i Bracers of Rock Binding?",a="Sono bracciali di pietra ricavati da elementali di roccia superiori di Maleterre. Lotwil Veriatus li studia per valutare la forza dei suoi ceppi.",al={"bracciali di roccia","legacci di pietra","oggetto bracciali"}},{q="Chi vuole questi bracciali?",a="Lotwil Veriatus vuole cinque Bracers of Rock Binding per le sue ricerche sulla forza dei suoi ceppi.",al={"chi ne ha bisogno","bracciali di lotwil","chi vuole i legacci di roccia"}},{q="Perché Lotwil ne ha bisogno?",a="Lotwil Veriatus crede che i bracciali degli elementali di roccia superiori lo aiuteranno a misurare la forza dei suoi ceppi.",al={"perché i bracciali","ricerche di lotwil","a cosa servono"}},{q="Da dove vengono i bracciali?",a="Gli elementali di roccia superiori di Maleterre portano Bracers of Rock Binding.",al={"dove trovare i bracciali","bracciali degli elementali di roccia","dove si trovano"}},{q="Perché Lotwil ne chiede cinque?",a="Lotwil ne chiede cinque per averne di scorta per le sue ricerche, perché il suo assistente Servo è famoso per smarrire reagenti e ricerche.",al={"quanti bracciali","ne servono cinque","perché così tanti"}}},fp="23,166,14.299.0,37.146.0,24.102.0,26.117.0,31.70.0,29.129.0"}
