P.entries["item:broken-armor-of-ana-thek"] = {n="Broken Armor of Ana'thek",s="Broken Armor of Ana'thek è un trofeo in frantumi dei Fendicranio della Valle di Rovotorto. Gan'zulah lo pretende come prova della sconfitta di Ana'thek.",h="Broken Armor of Ana'thek è un trofeo in frantumi dei Fendicranio della Valle di Rovotorto.",kw={"ana'thek","ana'thek the cruel","armatura spezzata","bubbling cauldron","gan'zulah","forte di grom'gol","fendicranio","valle di rovotorto"},sec={{t="La richiesta di un capotribù",b="Al Forte di Grom'gol, il capo Gan'zulah ti ordina di affrontare i Fendicranio sulle montagne orientali. Se sopravvivi allo scontro, pretende l'armatura spezzata del loro capo, Ana'thek the Cruel."}},faq={{q="Chi era Ana'thek?",a="Ana'thek the Cruel era il capo dei Fendicranio nella Valle di Rovotorto.",al={"chi è ana'thek","storia di ana'thek"}},{q="Perché Gan'zulah vuole l'armatura?",a="Gan'zulah pretende l'armatura in frantumi di Ana'thek come prova che hai sconfitto il capo dei Fendicranio.",al={"perché l'armatura","armatura di gan'zulah","cosa vuole gan'zulah"}},{q="Da dove viene l'armatura?",a="Broken Armor of Ana'thek proviene da Ana'thek the Cruel, nella Valle di Rovotorto.",al={"provenienza dell'armatura","da dove viene l'armatura","armatura di ana'thek"}},{q="Dove porto l'armatura?",a="Porta Broken Armor of Ana'thek al Bubbling Cauldron, al Forte di Grom'gol.",al={"consegnare l'armatura","dove portare l'armatura","bubbling cauldron"}}},fp="24,152,20.195.0,17.77.0,34.96.0,30.81.0,27.82.0"}
