P.entries["item:broken-tears"] = {n="Broken Tears",s="I Broken Tears sono frammenti di cristallo della caverna nel Covo di Bolgan, a sud di Desolanda. Warug dei Magram li chiede come prova che il clan può distruggere ciò che i Gelkis venerano.",h="I Broken Tears sono frammenti di cristallo della caverna nel Covo di Bolgan, a sud di Desolanda.",kw={"covo di bolgan","broken tears","centauro","desolanda","gelkis","magram","tears of theradras","warug"},sec={{t="Al Covo di Bolgan",b="Nel Covo di Bolgan, i Gelkis custodiscono cristalli chiamati tears of Theradras. Warug dei Magram vuole che li rompi e porti tre frammenti a Magram Village. Sostiene che Theradras non proteggerà i Gelkis e dice che ai Magram non serve protezione. La loro faida dà un significato ai cristalli spezzati."}},faq={{q="Cosa sono i Broken Tears?",a="I Broken Tears sono frammenti dei cristalli noti come tears of Theradras, custoditi in una caverna nel Covo di Bolgan.",al={"oggetto broken tears","cosa sono i tears"}},{q="Chi vuole i Broken Tears?",a="Warug, un centauro Magram a Magram Village, ti chiede di portargli tre Broken Tears.",al={"chi li vuole","warug e i tears"}},{q="Perché Warug li vuole?",a="Warug vuole distruggere i cristalli per dimostrare ai Gelkis che Theradras non li proteggerà.",al={"perché rompere i cristalli","motivo dei magram"}},{q="Da dove vengono i Broken Tears?",a="I tears of Theradras sono custoditi in una caverna nel Covo di Bolgan, a sud di Desolanda.",al={"dove trovare i broken tears","cristalli del covo di bolgan"}},{q="Cosa credono i Gelkis riguardo a Theradras?",a="I Gelkis credono che Theradras protegga i centauri; Warug considera sciocca questa convinzione.",al={"gelkis e theradras","chi protegge i gelkis"}}},fp="12,180,16.303.0,22.105.0,27.84.0,25.91.0,36.80.0,43.88.0"}
