P.entries["item:bundle-of-akiris-reeds"] = {n="Bundle of Akiris Reeds",s="A Bundle of Akiris Reeds è una consegna destinata al Corsaro Groy a Theramore. Lui la controlla per un cliente che ne vuole ancora.",h="A Bundle of Akiris Reeds è una consegna destinata al Corsaro Groy a Theramore.",kw={"akiris","canne di akiris","bloads","bundle of akiris reeds","corsaro groy","consegna","theramore"},sec={{t="Una nuova consegna",b="Il Corsaro Groy riceve le canne a Theramore dopo che Bloads gli manda un'altra consegna. Groy esamina il fascio, soddisfatto che accontenterà il suo cliente. Poi paga il corriere e lo congeda dai suoi moli."}},faq={{q="A chi è destinato il fascio?",a="Il Corsaro Groy riceve il Bundle of Akiris Reeds a Theramore per un cliente che ne vuole ancora.",al={"chi vuole le canne","cliente del bundle di akiris","a chi sono destinate le canne"}},{q="Dove devo portare il fascio?",a="Porta il Bundle of Akiris Reeds al Corsaro Groy a Theramore.",al={"dove portare le canne","posizione di groy","dove portare il fascio"}},{q="Chi manda il fascio?",a="Bloads ti chiede di portare la consegna al Corsaro Groy a Theramore.",al={"chi mi ha dato le canne","consegna di bloads","da dove viene"}},{q="Cosa ne fa Groy?",a="Groy esamina le canne e dice che un altro fascio farà piacere al suo cliente.",al={"groy controlla il fascio","a cosa serve la consegna","il cliente ne vuole ancora"}}},fp="22,120,16.215.0,22.92.0,27.64.0,21.69.0,26.71.0"}
P.entries["item:bundle-of-atal-ai-artifacts"] = {n="Bundle of Atal'ai Artifacts",s="Un fascio di artefatti Atal’ai viene portato dal Bacino delle Lacrime a un sacerdote esiliato negli Entroterre, per scoprirne lo scopo.",h="Un fascio di artefatti Atal’ai viene portato dal Bacino delle Lacrime a un sacerdote esiliato negli...",kw={"artefatti","atal’ai","fascio","chamber of blood","esilio","hakkar","jammal'an","bacino delle lacrime","evocazione","witherbark"},ang={["race:Troll"]="Il fascio riguarda i riti Atal’ai e un esiliato che vive tra i troll Witherbark negli Entroterre."},sec={{t="Una frase scritta col sangue",b="Una frase scritta col sangue, trovata vicino al Bacino delle Lacrime, condanna un sacerdote Atal’ai all’esilio. Gli artefatti raccolti lì sono destinati al sacerdote, che ha trovato rifugio tra i troll Witherbark negli Entroterre. Gli viene chiesto di rivelarne il vero uso."},{t="Lo scopo degli artefatti",b="L’esiliato riconosce nel fascio degli artefatti per l’evocazione. Jammal’an the Prophet guida i discepoli della Chamber of Blood verso il destino che hanno scelto, e resta da capire se Hakkar sia tornato al Temple."}},faq={{q="A cosa servono gli artefatti Atal’ai?",a="Il sacerdote esiliato riconosce gli artefatti Atal’ai come artefatti per l’evocazione.",al={"scopo degli artefatti","a cosa servono gli artefatti","fascio atal’ai"}},{q="Chi dovrebbe ricevere il fascio?",a="Il fascio è destinato a un sacerdote Atal’ai esiliato, che vive tra i troll Witherbark negli Entroterre.",al={"chi riceve gli artefatti","sacerdote atal’ai esiliato","destinatario del fascio"}},{q="Perché il sacerdote è stato esiliato?",a="La tribù Atal’ai ha condannato il sacerdote all’esilio. La sentenza non ne indica il motivo.",al={"motivo dell’esilio","sentenza del sacerdote atal’ai","cosa ha fatto il sacerdote"}},{q="Chi guida i discepoli della Chamber of Blood?",a="Jammal’an the Prophet guida i discepoli della Chamber of Blood.",al={"capo della chamber of blood","jammal’an","chi guida i discepoli"}},{q="Hakkar è tornato al Temple?",a="Il sacerdote si chiede se Hakkar sia tornato al Temple; il suo ritorno non è confermato.",al={"hakkar è tornato","hakkar al temple","hakkar è lì"}}},fp="27,139,24.254.0,24.213.1,37.76.1,38.105.0,26.94.1,41.68.0,34.90.1"}
