P.entries["item:caliph-scorpidsting-s-head"] = {n="Caliph Scorpidsting's Head",s="La Gadgetzan Water Company cerca prove contro Caliph Scorpidsting e offre una taglia tramite il Capo Ingegnere Segachiodi a Meccania.",h="La Gadgetzan Water Company cerca prove contro Caliph Scorpidsting e offre una taglia tramite il Capo...",kw={"bilgewhizzle","taglia","caliph scorpidsting","gadgetzan water company","testa di scorpidsting","tanaris","ricercato","wastewander"},sec={{t="Una taglia a Meccania",b="La Gadgetzan Water Company indica Caliph Scorpidsting come capo dei fuorilegge Wastewander. Accusa la sua banda di aver ucciso i suoi dipendenti, rubato le sue risorse e preso possesso delle sue proprietà. Offre una ricca taglia in cambio di prove della sua morte. Il Capo Ingegnere Segachiodi riceve la testa a Meccania."}},faq={{q="Chi vuole la testa di Caliph Scorpidsting?",a="La Gadgetzan Water Company offre una taglia in cambio di prove della morte di Caliph Scorpidsting. Il Capo Ingegnere Segachiodi riceve la testa a Meccania.",al={"chi vuole la testa","chi paga la taglia"}},{q="Perché Scorpidsting è ricercato?",a="La Gadgetzan Water Company accusa Caliph Scorpidsting e i suoi fuorilegge Wastewander di aver ucciso i suoi dipendenti, rubato le sue risorse e preso possesso delle sue proprietà.",al={"perché è ricercato","cosa ha fatto"}},{q="Chi è Caliph Scorpidsting?",a="Caliph Scorpidsting guida i fuorilegge Wastewander a Tanaris.",al={"scorpidsting","capo dei wastewander"}},{q="Dove devo portare la sua testa?",a="Porta la testa di Caliph Scorpidsting al Capo Ingegnere Segachiodi a Meccania.",al={"dove portare la testa","bilgewhizzle"}},{q="Di cosa è prova la testa?",a="La testa prova la morte di Caliph Scorpidsting, che la Gadgetzan Water Company cerca per pagare la taglia.",al={"proof of demise","perché la testa"}}},fp="26,137,21.307.0,37.146.0,27.161.0,27.61.0,26.77.1,26.106.1"}
