P.entries["item:captain-s-documents"] = {n="Documenti del Capitano",s="I Documenti del Capitano sono carte recuperate sotto i moli di Theramore. Nazeer Piccarossa li considera preziosi per ciò che potrebbero rivelare su Theramore e sull'Alleanza.",h="I Documenti del Capitano sono carte recuperate sotto i moli di Theramore.",kw={"alleanza","felcimura","documenti del capitano","comune","baule","nazeer piccarossa","theramore","moli di theramore"},ang={["faction:Horde"]="Come membro dell'Orda, ti mandano a recuperare delle carte che, secondo Nazeer, potrebbero rivelare la posizione di Theramore nei confronti dell'Alleanza e contribuire a proteggere gli interessi dell'Orda."},sec={{t="Sotto i moli",b="Le spie di Felcimura cercavano delle carte a bordo di una nave all'Isola di Theramore. Quando furono scoperte, una di loro infilò i documenti in un baule e lo gettò sotto i moli. Ora Nazeer Piccarossa ti manda a recuperare le carte, che ritiene possano riguardare la sicurezza dell'Orda."}},faq={{q="Cosa sono i Documenti del Capitano?",a="Sono carte sottratte da una nave all'Isola di Theramore dalle spie di Felcimura. Quando furono scoperte, le gettarono nelle acque sotto i moli.",al={"documenti del capitano","quelle carte","documenti di theramore"}},{q="Perché Nazeer vuole i documenti?",a="Nazeer Piccarossa crede che le carte contengano informazioni sui legami di Theramore con l'Alleanza e che queste conoscenze siano importanti per la sicurezza dell'Orda.",al={"perché nazeer li vuole","a cosa servono le carte","documenti dell'orda"}},{q="Dove sono stati trovati i documenti?",a="I documenti erano sigillati in un baule sotto i moli dell'Isola di Theramore.",al={"dove sono le carte","baule del capitano","carte dei moli di theramore"}},{q="Chi ha mandato le spie a Theramore?",a="Le spie venivano da Felcimura. Nazeer Piccarossa dirige le operazioni per recuperare le carte.",al={"chi le ha mandate","spie di felcimura","spie di theramore"}},{q="Cosa dicono le carte?",a="Le carte sono scritte in Comune e Nazeer ne tiene nascosto il contenuto. Non si sa con precisione cosa rivelino sui legami di Theramore con l'Alleanza.",al={"cosa c'è nei documenti","contenuto delle carte del capitano","rapporti tra theramore e l'alleanza"}}},fp="19,164,17.278.0,33.164.0,35.150.0,31.78.0,32.99.0,23.152.0"}
