P.entries["item:centaur-ear"] = {n="Centaur Ear",s="L’orecchio di un centauro prova che ne è stato ucciso uno in Desolanda. Sia l’Orda sia l’Alleanza li richiedono come segno dell’indebolimento dei clan.",h="L’orecchio di un centauro prova che ne è stato ucciso uno in Desolanda.",kw={"alleanza","centauro","centaur bounty","orecchio di centauro","caporale melkins","desolanda","felgur doppiotaglio","orda","presidio di nijel"},ang={["faction:Alliance"]="Al Presidio di Nijel, il Caporale Melkins definisce la raccolta di orecchie di centauro un servizio all’Alleanza e un passo verso la pace.",["faction:Horde"]="Per l’Orda, portare orecchie a Felgur Doppiotaglio dovrebbe indebolire i clan dei centauri e indicare quale insegna sta dietro al bagno di sangue."},sec={{t="Un macabro conteggio",b="In Desolanda si raccolgono orecchie di centauro tanto per l’Orda quanto per l’Alleanza. Felgur Doppiotaglio chiede ai viandanti dell’Orda di portargliene una grande scorta, convinto che un numero minore di centauri indebolirà la determinazione dei clan. Al Presidio di Nijel, il Caporale Melkins pretende orecchie in nome dell’Alleanza e della sua speranza di pace. Entrambe le insegne trasformano un macabro trofeo in una misura della loro lotta contro i centauri."}},faq={{q="Perché raccolgono orecchie di centauro?",a="Gli ufficiali dell’Orda e dell’Alleanza usano le orecchie di centauro come prova degli uccisi e come conteggio volto a indebolire i clan.",al={"perché le orecchie","a cosa servono le orecchie di centauro","a cosa servono le orecchie"}},{q="Chi vuole orecchie di centauro per l’Orda?",a="Felgur Doppiotaglio in Desolanda chiede ai viandanti dell’Orda di portargli una scorta di orecchie di centauro.",al={"chi vuole orecchie per l’orda","cosa vuole felgur","chi è felgur"}},{q="Chi vuole orecchie di centauro per l’Alleanza?",a="Il Caporale Melkins al Presidio di Nijel chiede ai viandanti dell’Alleanza di portargli orecchie di centauro.",al={"npc dell’alleanza che vuole orecchie","orecchie melkins","orecchie nijel"}},{q="Importa da quale clan provengono le orecchie?",a="Felgur Doppiotaglio dice che l’Orda può cacciare centauri di qualsiasi clan in Desolanda.",al={"quale clan","orecchie di qualsiasi centauro","orecchie dei clan"}}},fp="11,137,12.366.0,33.112.0,37.85.0,40.84.0,46.68.0"}
P.entries["item:centipaar-insect-parts"] = {n="Centipaar Insect Parts",s="Le Centipaar Insect Parts si raccolgono dai silithid nell'Antro Venefico di Tanaris. L'Alchimista Rollabomba le studia a Meccania per saperne di più sulle creature che prosciugano le pozze d'acqua della zona.",h="Le Centipaar Insect Parts si raccolgono dai silithid nell'Antro Venefico di Tanaris.",kw={"alchimista rollabomba","centipaar","meccania","parti d'insetto","antro venefico","silithid","tanaris","pozze d'acqua"},sec={{t="Parti dall'Antro",b="I silithid Centipaar dell'Antro Venefico forniscono parti per le indagini dell'Alchimista Rollabomba. Le studia a Meccania per scoprire cosa siano queste creature."}},faq={{q="Cosa sono le Centipaar Insect Parts?",a="Le Centipaar Insect Parts sono pezzi raccolti dai silithid nell'Antro Venefico di Tanaris perché l'Alchimista Rollabomba li studi.",al={"parti centipaar","parti d'insetto","parti di insetto"}},{q="Dove trovo le Centipaar Insect Parts?",a="I silithid Centipaar dell'Antro Venefico forniscono le parti che cerca l'Alchimista Rollabomba.",al={"dove trovare le parti","trovare parti centipaar","parti dell'antro venefico"}},{q="Chi vuole queste parti d'insetto?",a="L'Alchimista Rollabomba di Meccania vuole le Centipaar Insect Parts per studiare le creature dell'Antro Venefico.",al={"chi vuole le parti","parti per rollabomba","cosa vuole l'alchimista"}},{q="Perché si indagano questi insetti?",a="I silithid prosciugano le pozze d'acqua che un tempo si trovavano dove ora sorge l'Antro Venefico, e Rollabomba vuole scoprire cosa siano.",al={"perché gli insetti","pozze d'acqua","indagine sui silithid"}}},fp="22,190,19.165.0,32.117.0,38.82.0,29.111.0,36.131.0"}
P.entries["item:chains-of-hematus"] = {n="Catene di Hematus",s="Le Catene di Hematus sono vincoli che si trovano nella Piana di Lethlor. Garek o Gorn le cerca insieme ai vincoli di Blacklash, a Maleterre.",h="Le Catene di Hematus sono vincoli che si trovano nella Piana di Lethlor.",kw={"maleterre","drago nero","catene di hematus","hematus","piana di lethlor","runestone","seal of the earth"},sec={{t="Un sigillo infranto",b="Nella Piana di Lethlor, le Catene di Hematus vengono recuperate dopo aver liberato Hematus dal Seal of the Earth. Tre runestone prese dai pilastri della piana aprono quel sigillo. Garek o Gorn cerca le catene insieme ai vincoli di Blacklash, una volta uccisi i due draghi neri."}},faq={{q="Cosa sono le Catene di Hematus?",a="Le Catene di Hematus sono vincoli sottratti al drago nero Hematus nella Piana di Lethlor.",al={"catene di hematus","oggetto catene","vincoli di hematus"}},{q="Dove trovo le Catene di Hematus?",a="Hematus, nella Piana di Lethlor a Maleterre, porta le Catene di Hematus.",al={"dove trovare le catene","posizione delle catene","oggetto hematus"}},{q="Perché vogliono le catene?",a="Garek o Gorn chiede le Catene di Hematus insieme ai vincoli di Blacklash dopo aver ucciso i draghi.",al={"perché vogliono le catene","a cosa servono le catene","servono le catene di hematus"}},{q="Come si libera Hematus?",a="Le runestone dei Pillars of Diamond, Opal e Amethyst vengono inserite nel Seal of the Earth, liberando Hematus e Blacklash.",al={"liberare hematus","seal of the earth","runestone"}},{q="Chi vuole le catene?",a="Garek o Gorn cerca le Catene di Hematus, a seconda di chi ti ha mandato nella Piana di Lethlor.",al={"chi ha bisogno delle catene","catene garek","catene gorn"}}},fp="17,134,13.281.0,31.88.0,38.72.0,26.105.1,21.130.1,21.87.0"}
P.entries["item:charred-horn"] = {n="Corno Carbonizzato",s="A Roccavento, Furen Barbalunga ha bisogno di Corni Carbonizzati delle giovani chimere di Petrartiglio. La loro resistenza alle fiamme, ai colpi contundenti e alle dure forze elementali li rende utili per armature robuste.",h="A Roccavento, Furen Barbalunga ha bisogno di Corni Carbonizzati delle giovani chimere di Petrartiglio.",kw={"corno carbonizzato","chimera","cotta temprata al fuoco","furen barbalunga","petrartiglio","vette di petrartiglio"},ang={["class:Warrior"]="Per chi è guerriero, è l'occasione di recuperare Corni Carbonizzati in tutta Kalimdor per Furen Barbalunga, che ricompensa il viaggio pericoloso con una cotta temprata al fuoco fatta su misura.",["profession:Blacksmithing"]="Chi lavora come fabbro può vedere come i corni sfruttino il materiale dei predatori di Kalimdor, naturalmente temprato dal fuoco, per temprare gli anelli della maglia."},sec={{t="Un raro componente di forgiatura",b="Le chimere neonate e giovani delle Vette di Petrartiglio forniscono i Corni Carbonizzati. La loro resistenza alle fiamme e ai colpi contundenti li rende utili a Furen Barbalunga, un armaiolo nanico che lavora alla sua forgia a Roccavento. Gliene servono dodici per realizzare una cotta temprata al fuoco.\n\nFuren li unisce alle zanne velenose dei ragni delle Paludi Grigie, al flogisto delle Gallerie di Lamaspina e al corno galvanizzato di una matriarca delle chimere. I Corni Carbonizzati rinforzano gli anelli e le piastre della cotta con materiale trattato dal calore."}},faq={{q="Quali creature lasciano cadere i Corni Carbonizzati?",a="I Corni Carbonizzati si ricavano dalle chimere neonate e giovani delle Vette di Petrartiglio, su Kalimdor.",al={"dove ottenere il corno carbonizzato","chi lascia cadere il corno carbonizzato","fonte del corno carbonizzato"}},{q="Chi vuole questi corni a Roccavento?",a="I corni li vuole Furen Barbalunga, un armaiolo di Roccavento. Li usa per forgiare un robusto pettorale di maglia per guerrieri promettenti.",al={"chi usa il corno carbonizzato","consegna del corno carbonizzato","corni di furen barbalunga"}},{q="Perché Furen ne ha bisogno di così tanti?",a="Furen ha bisogno di dodici Corni Carbonizzati per avere abbastanza materiale trattato dal calore da rinforzare gli anelli e le piastre della sua cotta temprata al fuoco.",al={"perché 12 corni carbonizzati","scopo del corno carbonizzato"}},{q="Sono diversi dal Corno Galvanizzato?",a="Sì. I Corni Carbonizzati provengono dalle chimere più giovani di Petrartiglio. Il Corno Galvanizzato è un unico trofeo preso a una Matriarca delle Chimere, ed è molto più raro.",al={"corno galvanizzato e corno carbonizzato","differenza tra i corni"}}},fx={["785d7f85"]={q="Che cos'è un Corno Carbonizzato?",a="Un Corno Carbonizzato è un corno duro e annerito, ricavato dalle giovani chimere, ancora alle prime armi, che vagano tra le cime delle Vette di Petrartiglio. Temprati dal rigido clima di montagna e dalla natura elementale di queste bestie, i corni hanno una resistenza unica, che ne fa una materia prima pregiata per lavori di forgiatura specializzati.",al={"che cos'è il corno carbonizzato","storia del corno carbonizzato","notizie sul corno carbonizzato"}}},fp="12,187,25.490.0,34.92.0,35.132.0,39.133.0,45.154.0"}
