P.entries["item:cleverly-encrypted-letter"] = {n="Cleverly Encrypted Letter",s="La Cleverly Encrypted Letter è un biglietto illeggibile trovato nelle Alture di Colletorto. Lo Storico Dibbs lo invia al Prospettore Piccatonante a Forgiardente, sperando che la sua esperienza ne riveli il significato.",h="La Cleverly Encrypted Letter è un biglietto illeggibile trovato nelle Alture di Colletorto.",kw={"cleverly encrypted letter","lettera cifrata","salone degli esploratori","forgiardente","lettera","storico dibbs","prospettore piccatonante","riva del sud"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, porti la lettera da Riva del Sud a Forgiardente, collegando due insediamenti dove gli studiosi potrebbero aiutarti a scoprirne il significato."},sec={{t="Un biglietto illeggibile",b="Su un tavolo nelle Alture di Colletorto, una lettera spicca tra le altre. La sua scrittura è cifrata e indecifrabile, così la porti allo Storico Dibbs a Riva del Sud. Non ha mai visto questo tipo di cifratura e dubita che le sue conoscenze siano sufficienti. Ti manda dal suo collega Prospettore Piccatonante a Forgiardente, esperto in enigmi del genere."}},faq={{q="Da dove viene la lettera?",a="La lettera è stata trovata tra altre lettere su un tavolo nelle Alture di Colletorto.",al={"origine della lettera","dove è stata trovata","biglietto cifrato"}},{q="Perché la lettera è cifrata?",a="La sua scrittura usa un tipo di cifratura che lo Storico Dibbs non ha mai visto. Il suo scopo è ignoto.",al={"perché è cifrata","qual è il codice","codice della lettera"}},{q="Chi sta cercando di leggere la lettera?",a="Lo Storico Dibbs a Riva del Sud esamina la lettera, poi ti manda dal suo collega Prospettore Piccatonante a Forgiardente.",al={"chi la decifra","chi sa leggerla","lettore della lettera"}},{q="Dove posso portare la lettera?",a="Porta la lettera dal Prospettore Piccatonante nella Biblioteca del Salone degli Esploratori di Forgiardente. Ti manda lo Storico Dibbs.",al={"dove portare la lettera","letter to stormpike","a chi la mostro"}}},fp="25,197,18.343.0,31.75.0,28.101.0,33.118.0,28.115.0"}
