P.entries["item:crude-charm"] = {n="Crude Charm",s="Un Crude Charm è portato dai centauri Kolkar in Desolanda. Uthek il Saggio li vuole per mostrare ai Kolkar che la loro magia è debole.",h="Un Crude Charm è portato dai centauri Kolkar in Desolanda.",kw={"centauro","crude charm","desolanda","gelkis","kolkar","strange alliance","uthek il saggio"},sec={{t="Gli amuleti dei Kolkar",b="Uthek il Saggio vuole che i Crude Charms dei Kolkar siano portati al Villaggio dei Gelkis, per gettarli nel fuoco come prova che la magia dei Kolkar non può proteggerli. Il suo disprezzo per i Kolkar è evidente e si aspetta che la loro paura li indebolisca ancora di più."}},faq={{q="Che cos'è un Crude Charm?",a="Un Crude Charm è portato dai centauri Kolkar in Desolanda ed è ricercato da Uthek il Saggio al Villaggio dei Gelkis.",al={"crude charm","amuletto kolkar"}},{q="Chi vuole i Crude Charms?",a="Uthek il Saggio del Villaggio dei Gelkis vuole i Crude Charms dei Kolkar.",al={"chi vuole i crude charms","amuleti ut hek"}},{q="Perché Uthek vuole i Crude Charms?",a="Uthek intende bruciare i Crude Charms dei Kolkar per dimostrare che la loro magia è debole.",al={"perché gli amuleti","a cosa servono gli amuleti"}},{q="Che cosa vogliono i Gelkis dai Kolkar?",a="Uthek vuole dimostrare ai Kolkar che la loro magia è patetica e crede che la paura li renderà ancora più deboli.",al={"gelkis kolkar","perché assaltare i kolkar"}}},fp="11,130,20.229.0,22.103.0,21.65.0,33.71.0,40.116.0"}
